DECLARE @sns AS TABLE ([ID] INT IDENTITY(1, 1), [NSN] NVARCHAR(MAX), [OSN] NVARCHAR(MAX));

;

BEGIN TRAN;


SELECT * FROM [Orders]
INNER JOIN
	@sns
ON	
	[Orders].[Serial Number] = [@sns].[NSN]


	UPDATE
		[Orders]
	SET
		[Serial Number] = [OSN]
		, [Special Instructions] = (CASE
			WHEN
				PATINDEX('% 2022-09-21 12PM%', [Special Instructions]) > 0
			THEN
				LEFT([Special Instructions], PATINDEX('% 2022-09-21 12PM%', [Special Instructions]))
			ELSE
				[Special Instructions]
		END)
	FROM
		@sns
	WHERE
		[@sns].[NSN] = [Orders].[Serial Number]

		
SELECT * FROM [Orders]
INNER JOIN
	@sns
ON	
	[Orders].[Serial Number] = [@sns].[NSN]

	
SELECT [Serial Number], [Special Instructions], * FROM [Orders]
INNER JOIN
	@sns
ON	
	[Orders].[Serial Number] = [@sns].[OSN]
ORDER BY
	[Orders].[Serial Number]


SELECT [Serial Number] FROM [Orders]
INNER JOIN
	@sns
ON	
	[Orders].[Serial Number] = [@sns].[OSN]
GROUP BY
	[Serial Number]
HAVING COUNT(*) > 1
ORDER BY
	[Orders].[Serial Number]



ROLLBACK;
COMMIT;